interface Discount {
    int apply(int price);
}
class NoDiscount implements Discount {
    public int apply(int price) { return price; }
}
class HalfDiscount implements Discount {
    public int apply(int price) { return price / 2; }
}
// 새 할인 정책 추가 시 기존 코드는 안 건드리고 클래스만 추가하면 됨

int applyDiscount(String type, int price) {
    if (type.equals("NONE")) return price;
    else if (type.equals("HALF")) return price / 2;
    // 새 할인 정책이 생길 때마다 여기 else if를 계속 추가...
    return price;
}
